 void KeyboardBrightnessControl::onProfileLoad(const QString &previousProfile, const QString &newProfile)
 {
+    if (!m_turnOffDuringDay) {
+        applyProfileBrightness(previousProfile, newProfile);
+        return;
+    }
+
+    if (!m_scheduleProvider) {
+        m_scheduleProvider = std::make_unique<KDarkLightScheduleProvider>();
+        connect(m_scheduleProvider.get(), &KDarkLightScheduleProvider::scheduleChanged, this, &KeyboardBrightnessControl::updateDayNight);
+
+        m_skewNotifier = std::make_unique<KSystemClockSkewNotifier>();
+        connect(m_skewNotifier.get(), &KSystemClockSkewNotifier::skewed, this, &KeyboardBrightnessControl::updateDayNight);
+        m_skewNotifier->setActive(true);
+    }
+
+    // Wait for the actual schedule rather than acting on the default one
+    KDarkLightScheduleProvider::poll().then(this, [this, previousProfile, newProfile](QFuture<KDarkLightSchedule>) {
+        if (!m_scheduleProvider) {
+            return;
+        }
+        m_isDaytime.reset();
+        updateDayNight();
+        if (!m_isDaytime.value_or(false)) {
+            applyProfileBrightness(previousProfile, newProfile);
+        }
+    });
+}
+
+void KeyboardBrightnessControl::onProfileUnload()
+{
+    m_dayNightTimer.stop();
+    m_scheduleProvider.reset();
+    m_skewNotifier.reset();
+    m_isDaytime.reset();
+}
+
+void KeyboardBrightnessControl::applyProfileBrightness(const QString &previousProfile, const QString &newProfile)
+{
+    if (m_defaultValue < 0) {
+        return;
+    }
+
     const int absoluteKeyboardBrightnessValue = qRound(m_defaultValue / 100.0 * keyboardBrightnessMax());

     // if the current profile is more conservative than the previous one and the
@@ -94,12 +143,61 @@ bool KeyboardBrightnessControl::isSupported()

 bool KeyboardBrightnessControl::loadAction(const PowerDevil::ProfileSettings &profileSettings)
 {
-    if (!profileSettings.useProfileSpecificKeyboardBrightness()) {
-        return false;
+    m_defaultValue = profileSettings.useProfileSpecificKeyboardBrightness() ? profileSettings.keyboardBrightness() : -1;
+    m_nightValue = profileSettings.keyboardBrightness();
+    m_turnOffDuringDay = profileSettings.turnOffKeyboardBacklightDuringDay();
+
+    return m_defaultValue >= 0 || m_turnOffDuringDay;
+}
+
+static QDateTime transitionBreakPoint(const KDarkLightTransition &transition)
+{
+    return transition.startDateTime() + (transition.endDateTime() - transition.startDateTime()) / 2;
+}
+
+void KeyboardBrightnessControl::updateDayNight()
+{
+    const QDateTime now = QDateTime::currentDateTime();
+    const KDarkLightSchedule schedule = m_scheduleProvider->schedule();
+    const auto previousTransition = schedule.previousTransition(now);
+    const auto nextTransition = schedule.nextTransition(now);
+    if (!previousTransition || !nextTransition) {
+        return;
+    }
+
+    // Like automatic theme switching, switch halfway through a transition
+    bool isDaytime;
+    QDateTime nextSwitch;
+    if (now < transitionBreakPoint(*previousTransition)) {
+        isDaytime = previousTransition->type() == KDarkLightTransition::Evening;
+        nextSwitch = transitionBreakPoint(*previousTransition);
+    } else {
+        isDaytime = previousTransition->type() == KDarkLightTransition::Morning;
+        nextSwitch = transitionBreakPoint(*nextTransition);
     }
+    m_dayNightTimer.start(std::max<qint64>(now.msecsTo(nextSwitch), 0));

-    m_defaultValue = profileSettings.keyboardBrightness();
-    return true;
+    if (m_isDaytime == isDaytime) {
+        return;
+    }
+    m_isDaytime = isDaytime;
+
+    const int brightness = keyboardBrightness();
+    if (isDaytime) {
+        if (brightness > 0) {
+            qCDebug(POWERDEVIL) << "Turning off keyboard backlight for the day";
+            m_brightnessBeforeDay = brightness;
+            core()->keyboardBrightnessController()->setBrightness(0);
+        }
+    } else if (brightness == 0) {
+        qCDebug(POWERDEVIL) << "Turning on keyboard backlight for the night";
+        int value = m_brightnessBeforeDay;
+        if (m_defaultValue >= 0 || value <= 0) {
+            value = qRound((m_defaultValue >= 0 ? m_defaultValue : m_nightValue) / 100.0 * keyboardBrightnessMax());
+        }
+        core()->keyboardBrightnessController()->setBrightness(std::max(value, 1));
+        m_brightnessBeforeDay = 0;
+    }
 }

 void KeyboardBrightnessControl::onBrightnessChangedFromController(const KeyboardBrightnessLogic::BrightnessInfo &info)
